package yagen.waitmydawn.kb.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;
class MediaRequestPlannerTest {
 final MediaRequestPlanner.Subject fire=new MediaRequestPlanner.Subject("iceandfire:fire_dragon","ENTITY",List.of("火龙","Fire Dragon"));
 final MediaRequestPlanner.Subject ice=new MediaRequestPlanner.Subject("iceandfire:ice_dragon","ENTITY",List.of("冰龙","Ice Dragon"));
 MediaRequestPlanner.Plan plan(String q){return MediaRequestPlanner.plan(q,List.of(fire,ice),Set.of());}
 @Test void oneEntityGetsIndependentGrowthRequests(){var p=plan("比较火龙的一阶与五阶外观");assertEquals(2,p.requests().size());assertTrue(p.requests().get(0).query().contains("growth_stage=1"));assertTrue(p.requests().get(1).query().contains("growth_stage=5"));}
 @Test void sharedColorIsRetainedWhilePairedColorAndSexStayPaired(){var shared=plan("比较红色火龙的一阶与五阶");assertEquals(2,shared.requests().size());assertTrue(shared.requests().stream().allMatch(r->r.query().contains("红色")));var paired=plan("展示火龙红色雌性与绿色雄性的外观");assertEquals(2,paired.requests().size());assertTrue(paired.requests().get(0).query().contains("sex=female"));assertFalse(paired.requests().get(0).query().contains("绿色"));assertTrue(paired.requests().get(1).query().contains("sex=male"));}
 @Test void colorsDoNotLeakAcrossEntities(){var p=plan("比较红色火龙和蓝色冰龙");assertEquals(2,p.requests().size());assertTrue(p.requests().get(0).query().contains("红色"));assertFalse(p.requests().get(0).query().contains("蓝色"));assertTrue(p.requests().get(1).query().contains("蓝色"));}
 @Test void sharedSuffixAppliesToBothEntities(){var p=plan("比较火龙和冰龙的一阶与五阶");assertEquals(4,p.requests().size());assertEquals(2,p.requests().stream().filter(r->r.query().contains("growth_stage=1")).count());}
 @Test void unknownExplicitValuesAreRetainedAndIdentityColorIsNotAState(){assertTrue(plan("火龙 growth_stage=99").requests().getFirst().query().contains("growth_stage=99"));var wool=new MediaRequestPlanner.Subject("minecraft:red_wool","ITEM",List.of("红色羊毛"));var p=MediaRequestPlanner.plan("展示红色羊毛",List.of(wool),Set.of());assertFalse(p.requests().getFirst().query().contains("红色"));}
 @Test void equipmentIsAConstraintRatherThanAnotherSubject(){var cow=new MediaRequestPlanner.Subject("minecraft:cow","ENTITY",List.of("牛"));var helmet=new MediaRequestPlanner.Subject("minecraft:diamond_helmet","ITEM",List.of("钻石头盔"));var p=MediaRequestPlanner.plan("展示牛穿戴钻石头盔的外观",List.of(cow,helmet),Set.of());assertEquals(1,p.requests().size());assertTrue(p.requests().getFirst().query().contains("钻石头盔"));}
 @Test void budgetIsExplicitAndAmbiguousNamesAreNotGuessed(){var a=new MediaRequestPlanner.Subject("a:dragon","ENTITY",List.of("龙"));var b=new MediaRequestPlanner.Subject("b:dragon","ENTITY",List.of("龙"));var p=MediaRequestPlanner.plan("展示龙",List.of(a,b),Set.of());assertTrue(p.requests().isEmpty());assertFalse(p.warnings().isEmpty());}
 @Test void itemKindDoesNotBecomeDroppedItemEntity(){var arrow=new MediaRequestPlanner.Subject("minecraft:arrow","BOTH",List.of("箭"));var item=new MediaRequestPlanner.Subject("minecraft:item","ENTITY",List.of("物品","Item"));var p=MediaRequestPlanner.plan("对比箭实体和箭物品的图片；缺少实体图时请说明。",List.of(arrow,item),Set.of("minecraft:arrow"));assertEquals(2,p.requests().size());assertEquals("ENTITY",p.requests().get(0).kind());assertEquals("ITEM",p.requests().get(1).kind());assertTrue(p.requests().stream().allMatch(r->r.subject().registry().equals("minecraft:arrow")));}
 @Test void namespacedVariantIsNotAnotherObject(){var cat=new MediaRequestPlanner.Subject("minecraft:cat","ENTITY",List.of("猫","Cat"));var p=MediaRequestPlanner.plan("展示 minecraft:cat variant=minecraft:tabby 实体外观",List.of(cat),Set.of());assertEquals(1,p.requests().size());assertTrue(p.requests().getFirst().query().contains("variant=minecraft:tabby"));}
 @Test void nativeBreedAndBiomeNamesRemainSeparateAxes(){var cat=new MediaRequestPlanner.Subject("minecraft:cat","ENTITY",List.of("猫"));var p=MediaRequestPlanner.plan("对比虎斑和暹罗猫的外观",List.of(cat),Set.of());assertEquals(2,p.requests().size());assertTrue(p.requests().get(0).query().contains("虎斑"));assertTrue(p.requests().get(1).query().contains("暹罗"));var villager=new MediaRequestPlanner.Subject("minecraft:villager","ENTITY",List.of("村民"));var v=MediaRequestPlanner.plan("展示沙漠的图书管理员村民",List.of(villager),Set.of());assertEquals(1,v.requests().size());assertFalse(v.requests().getFirst().query().contains("unsupported_conflict"));assertTrue(v.requests().getFirst().query().contains("沙漠"));assertTrue(v.requests().getFirst().query().contains("图书管理员"));}
}
